const settle = (max) => {
  let last = -1, stable = 0;
  for (let i = 0; i < max; i++) {
    g.renderOnce(1/60);
    const a = g.lightProbe().adaptation;
    const e = a ? a.autoGain : 0;
    if (i > 150 && Math.abs(e - last) < 2e-3) { if (++stable > 20) return i; } else stable = 0;
    last = e;
  }
  return max;
};
for (const c of g.rig.circuits.keys()) g.rig.setCircuit(c, true);
g.engine.autoQuality = false;
const r = g.world.goto('duct');
const p = (r && r.position) || g.world.spawn;
g.lookOpen(p, ((r && r.yaw) || 0) + 0, 0);
if (g.flashlight) {
  g.flashlight.enabled = true;
  g.flashlight.isOn = true;
  g.flashlight.battery = 1;
  // beamStrength ramps at ~24/s toward the target; settle() runs long enough,
  // but seed it so the first frames are not a fade-in.
  g.flashlight.beamStrength = 1;
}
const frames = settle(700);
const pr = g.lightProbe();
console.log('LAMP ' + JSON.stringify({ shot: 'duct_h0_on',
  lamp: true, beam: g.flashlight ? +g.flashlight.beamStrength.toFixed(2) : null,
  zone: pr.zone, head: pr.directAtHead, fillUp: pr.fillUp,
  adaptation: pr.adaptation, settleFrames: frames, eye: +g.player.position.y.toFixed(2) }));

